contracts/SLisBNB.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.0;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";

import "./interfaces/ISLisBNB.sol";

contract SLisBNB is ISLisBNB, ERC20Upgradeable, AccessControlUpgradeable {
    address private stakeManager;

    string private constant _name = "Staked Lista BNB";

    string private constant _symbol = "slisBNB";

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address _admin) external override initializer {
        __AccessControl_init();
        __ERC20_init(_name, _symbol);

        require(_admin != address(0), "zero address provided");

        _setupRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    function name() public pure override returns (string memory) {
        return _name;
    }

    function symbol() public pure override returns (string memory) {
        return _symbol;
    }

    function mint(address _account, uint256 _amount)
        external
        override
        onlyStakeManager
    {
        _mint(_account, _amount);
    }

    function burn(address _account, uint256 _amount)
        external
        override
        onlyStakeManager
    {
        _burn(_account, _amount);
    }

    function setStakeManager(address _address)
        external
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(stakeManager != _address, "Old address == new address");
        require(_address != address(0), "zero address provided");

        stakeManager = _address;

        emit SetStakeManager(_address);
    }

    modifier onlyStakeManager() {
        require(
            msg.sender == stakeManager,
            "Accessible only by StakeManager Contract"
        );
        _;
    }
}

contracts/interfaces/ISLisBNB.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.0;

import "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";

/// @title SLisBNB interface
interface ISLisBNB is IERC20Upgradeable {
    function initialize(address _manager) external;

    function mint(address _account, uint256 _amount) external;

    function burn(address _account, uint256 _amount) external;

    function setStakeManager(address _address) external;

    event SetStakeManager(address indexed _address);
}
